import {studioSources} from './studio-data.js';
import {studioMilestones} from './studio-science.js';
import {createScaleJourney} from './studio-scale.js';
import {createGeneCraft} from './studio-gene.js';
import {createImmuneJourney} from './studio-immune.js';
import {createScientistPortal,createFieldStudio} from './studio-history.js';
const tabs=[['scale','Vũ trụ sống','01'],['gene','GeneCraft','02'],['immune','BioDefense','03'],['history','Cổng nhà khoa học','04'],['field','STEM tại bàn','05']];
export function createDiscoveryStudio(api){
 const root=document.querySelector('#discovery-studio');let active=false,selected='scale';const modules={};
 root.innerHTML=`<div class="studio-intro"><div><div class="eyebrow">06 / XƯỞNG KHÁM PHÁ VNSCAPE</div><h1 data-page-heading tabindex="-1">Thử một ý tưởng.<br><em>Mở một thế giới.</em></h1><p>Đi từ khu rừng đến mã di truyền. Gặp một cách nghĩ mới.<br> Mỗi khám phá bắt đầu bằng câu hỏi của bạn.</p></div><div class="studio-passport"><span class="studio-kicker">DẤU CHÂN KHÁM PHÁ</span><strong id="studio-progress-count">0 <span>/ ${studioMilestones.length}</span></strong><div class="studio-progress-track"><span id="studio-progress-fill"></span></div><p>Mỗi cột mốc mới +15 XP.<br>Ghi chép đi cùng bạn trong sổ tay.</p><a href="#/notebook">Mở sổ tay của tôi ↗</a></div><div class="studio-intro-leaf" aria-hidden="true"></div></div><div class="studio-tablist" role="tablist" aria-label="Các không gian trong xưởng khám phá">${tabs.map(([id,title,n],i)=>`<button type="button" id="studio-tab-${id}" role="tab" data-studio-tab="${id}" aria-selected="${i===0}" aria-controls="studio-panel-${id}" tabindex="${i===0?0:-1}"><span>${n}</span>${title}</button>`).join('')}</div>${tabs.map(([id])=>`<section class="studio-panel" id="studio-panel-${id}" role="tabpanel" aria-labelledby="studio-tab-${id}" ${id!=='scale'?'hidden':''}><div data-studio-module="${id}"></div><details class="studio-source-list"><summary>Nguồn khoa học & cách biên soạn</summary><p>Nội dung diễn giải bằng tiếng Việt; sơ đồ và tình huống do VNScape biên soạn. Các mô hình nêu rõ giả định và không thay thế dữ liệu thực nghiệm.</p><ul>${studioSources[id].map(([title,url])=>`<li><a href="${url}" target="_blank" rel="noopener noreferrer">${title} ↗</a></li>`).join('')}</ul></details></section>`).join('')}<div class="studio-storage-note"><span aria-hidden="true">✳</span><p>Khám phá theo nhịp của bạn. Tiến độ và sổ tay lưu trên trình duyệt hiện tại; xuất sổ để giữ bản sao khi đổi thiết bị.</p><a href="#/notebook">Sổ tay của tôi →</a></div>`;
 function update(){const count=api.getState().completedStudio.length;root.querySelector('#studio-progress-count').innerHTML=`${count} <span>/ ${studioMilestones.length}</span>`;root.querySelector('#studio-progress-fill').style.width=`${count/studioMilestones.length*100}%`}
 function award(id,message){const s=api.getState();if(!studioMilestones.includes(id)||s.completedStudio.includes(id))return false;s.completedStudio.push(id);api.trackActivity?.();const saved=api.persist();update();api.toast(saved?`${message} · +15 XP`:`${message} · +15 XP trong phiên này; bộ nhớ trình duyệt chưa lưu được.`);return true}
 function saveNote(title,body){if(api.getState().notes.length>=100){api.toast('Sổ đã có 100 trang ghi chép. Hãy xuất bản sao rồi sắp xếp lại trước khi thêm.');return false}const stored=api.addNote(title,body);api.toast(stored?'Đã lưu vào sổ tay của bạn.':'Ghi chép đang ở trong phiên này; hãy xuất sổ vì trình duyệt chưa lưu được dữ liệu.');return true}
 const studioAPI={...api,award,saveNote,isComplete:id=>api.getState().completedStudio.includes(id)};
 const creators={scale:createScaleJourney,gene:createGeneCraft,immune:createImmuneJourney,history:createScientistPortal,field:createFieldStudio};
 function ensure(id){return modules[id]||=creators[id](root.querySelector(`[data-studio-module="${id}"]`),studioAPI)}
 function select(id,focus=false){if(!creators[id])return;modules[selected]?.setActive(false);selected=id;root.querySelectorAll('[data-studio-tab]').forEach(b=>{const current=b.dataset.studioTab===id;b.setAttribute('aria-selected',String(current));b.tabIndex=current?0:-1});root.querySelectorAll('.studio-panel').forEach(p=>{p.hidden=p.id!=='studio-panel-'+id});ensure(id).setActive(active&&!document.hidden);if(focus)root.querySelector('#studio-tab-'+id).focus();update()}
 root.querySelectorAll('[data-studio-tab]').forEach(b=>b.addEventListener('click',()=>select(b.dataset.studioTab)));root.querySelector('.studio-tablist').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const ids=tabs.map(t=>t[0]),i=ids.indexOf(selected),next=e.key==='Home'?0:e.key==='End'?ids.length-1:(i+(e.key==='ArrowRight'?1:ids.length-1))%ids.length;select(ids[next],true)});
 document.addEventListener('visibilitychange',()=>modules[selected]?.setActive(active&&!document.hidden));
 window.addEventListener('pagehide',()=>Object.values(modules).forEach(m=>m.setActive(false)));
 window.addEventListener('beforeunload',e=>{if(Object.values(modules).some(m=>m.hasDraft?.())){e.preventDefault();e.returnValue=''}});
 update();return {setActive(value){active=value;if(value)ensure(selected);modules[selected]?.setActive(value&&!document.hidden);update()},select};
}
